// Additive, idempotent migrations also upgrade existing on-disk databases.
fn add_column(
    db: &Connection,
    table: &str,
    column: &str,
    definition: &str,
) -> rusqlite::Result<()> {
    let mut stmt = db.prepare(&format!("PRAGMA table_info({table})"))?;
    let names = stmt
        .query_map([], |r| r.get::<_, String>(1))?
        .collect::<Result<Vec<_>, _>>()?;
    if !names.iter().any(|name| name == column) {
        db.execute_batch(&format!(
            "ALTER TABLE {table} ADD COLUMN {column} {definition}"
        ))?;
    }
    Ok(())
}

fn get_quiz(db: &Connection, id: i64) -> AppResult<Quiz> {
    db.query_row(
        "SELECT id, title, number_of_winners FROM quizzes WHERE id=?",
        [id],
        |row| {
            Ok(Quiz {
                id: row.get(0)?,
                title: row.get(1)?,
                number_of_winners: row.get(2)?,
            })
        },
    )
    .optional()?
    .ok_or(AppError::NotFound)
}
fn get_questions(db: &Connection, quiz_id: i64) -> AppResult<Vec<Question>> {
    let mut stmt =
        db.prepare("SELECT id, text, active FROM questions WHERE quiz_id=? ORDER BY position, id")?;
    let mut questions = stmt
        .query_map([quiz_id], |row| {
            Ok(Question {
                id: row.get(0)?,
                text: row.get(1)?,
                active: row.get(2)?,
                options: vec![],
            })
        })?
        .collect::<Result<Vec<_>, _>>()?;
    let mut stmt =
        db.prepare("SELECT text, correct FROM options WHERE question_id=? ORDER BY position, id")?;
    for question in &mut questions {
        question.options = stmt
            .query_map([question.id], |row| {
                Ok(Choice {
                    text: row.get(0)?,
                    correct: row.get(1)?,
                })
            })?
            .collect::<Result<Vec<_>, _>>()?;
    }
    Ok(questions)
}
fn get_question(db: &Connection, quiz_id: i64, question_id: i64) -> AppResult<Question> {
    get_questions(db, quiz_id)?
        .into_iter()
        .find(|q| q.id == question_id)
        .ok_or(AppError::NotFound)
}
fn verify_csrf(app: &App, fields: &Fields) -> AppResult<()> {
    if fields
        .get("csrf")
        .is_some_and(|token| constant_eq(token.as_bytes(), app.csrf.as_bytes()))
    {
        Ok(())
    } else {
        Err(AppError::Forbidden)
    }
}
fn constant_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    a.iter().zip(b).fold(0u8, |diff, (a, b)| diff | (a ^ b)) == 0
}
fn quiz_url(id: i64) -> String {
    format!("/moderate/quizzes/{id}")
}
fn question_url(quiz_id: i64, question_id: i64) -> String {
    format!("{}/questions/{question_id}", quiz_url(quiz_id))
}

async fn protect(State(app): State<AppState>, request: Request, next: Next) -> Response {
    let path = request.uri().path();
    if path != "/moderate" && !path.starts_with("/moderate/") {
        return next.run(request).await;
    }
    let credentials = request
        .headers()
        .get(header::AUTHORIZATION)
        .and_then(|h| h.to_str().ok())
        .and_then(|value| {
            let (scheme, encoded) = value.split_once(' ')?;
            if !scheme.eq_ignore_ascii_case("Basic") {
                return None;
            }
            STANDARD.decode(encoded.trim()).ok()
        });
    if !credentials.is_some_and(|supplied| constant_eq(&supplied, app.credentials.as_bytes())) {
        return (
            StatusCode::UNAUTHORIZED,
            [
                (
                    header::WWW_AUTHENTICATE,
                    "Basic realm=\"Quizzy moderator\", charset=\"UTF-8\"",
                ),
                (header::CACHE_CONTROL, "no-store"),
            ],
            "Moderator authentication required",
        )
            .into_response();
    }
    let mut response = next.run(request).await;
    response
        .headers_mut()
        .insert(header::CACHE_CONTROL, HeaderValue::from_static("no-store"));
    response
